 static X509Certificate certificate(String value){try{byte[]data=value.contains("BEGIN CERTIFICATE")?value.getBytes(java.nio.charset.StandardCharsets.US_ASCII):Base64.getDecoder().decode(value);try(var in=new ByteArrayInputStream(data)){return (X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(in);}}catch(Exception e){throw new IllegalArgumentException("Invalid certificate");}}
