  var names=request.getSubject().getRDNs(BCStyle.CN);if(names.length!=1||names[0].size()!=1)throw new IllegalArgumentException("CSR requires exactly one common name");String common=IETFUtils.valueToString(names[0].getFirst().getValue());String suffix=cn(root),shortName=common.contains(".")?common.substring(0,common.indexOf('.')):"";if(!common.equals(shortName+"."+suffix)||!shortName.matches("[A-Z][A-Za-z0-9]{0,62}"))throw new IllegalArgumentException("CSR common name must belong to the local cloud");
