 @Override void register()throws Exception{registerSystem(m("role","certificate-authority","security","X.509/mTLS"));var ids=new ArrayList<String>();ids.add(registerService("certificateSigning","1.0.0","/certificate-authority",m("sign",op("POST","/sign")),m("systemVersion","5.2.2")));ids.add(registerService("certificateValidation","1.0.0","/certificate-authority",m("check-certificate",op("POST","/checkCertificate"),"check-trusted-key",op("POST","/checkTrustedKey"),"get-crl",op("GET","/crl")),m("systemVersion","5.2.2")));ids.add(registerService("certificateAuthorityManagement","1.0.0","/certificate-authority",m("list-certificates",op("GET","/mgmt/certificates"),"revoke-certificate",op("DELETE","/mgmt/certificates/{id}"),"revoke-certificate-by-content",op("POST","/mgmt/revocations"),"list-keys",op("GET","/mgmt/keys"),"add-key",op("PUT","/mgmt/keys"),"delete-key",op("DELETE","/mgmt/keys/{id}")),m("systemVersion","5.2.2")));registerMonitor("certificateAuthority",ids);registered(ids);}
 @Override void startWorkers(){periodic(this::publishCrl,envInt("CRL_REFRESH_SECONDS",3600));periodic(()->Messaging.nativeMonitor(this,"certificateAuthority",monitor,m("state","running","version","5.2.2","issuedCertificates",db.query("SELECT count(*) AS n FROM issued_certificates").getFirst().get("n"),"revokedCertificates",db.query("SELECT count(*)AS n FROM issued_certificates WHERE revoked_at IS NOT NULL").getFirst().get("n"),"trustedKeys",db.query("SELECT count(*)AS n FROM trusted_keys").getFirst().get("n"))),envInt("MONITOR_INTERVAL_SECONDS",30));}
 @Override public void close(){monitor.close();super.close();}
 static final class CAStore{
  final Database db;CAStore(Database db)throws Exception{this.db=db;db.schema("CREATE TABLE IF NOT EXISTS issued_certificates(id INTEGER PRIMARY KEY AUTOINCREMENT,serial_number TEXT UNIQUE NOT NULL,common_name TEXT NOT NULL,created_by TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,revoked_at TEXT,certificate_pem TEXT NOT NULL)","CREATE TABLE IF NOT EXISTS trusted_keys(id INTEGER PRIMARY KEY AUTOINCREMENT,public_key_pem TEXT UNIQUE NOT NULL,description TEXT NOT NULL DEFAULT '',valid_after TEXT NOT NULL,valid_before TEXT NOT NULL,created_at TEXT NOT NULL)");}
  long add(X509Certificate cert,String common,String actor,String revoked)throws Exception{return db.transaction(c->{Database.update(c,"INSERT INTO issued_certificates(serial_number,common_name,created_by,valid_from,valid_until,revoked_at,certificate_pem)VALUES(?,?,?,?,?,?,?)",cert.getSerialNumber().toString(),common,actor,cert.getNotBefore().toInstant().toString(),cert.getNotAfter().toInstant().toString(),revoked,pem(cert));return Database.inserted(c);});}
  Map<String,Object>bySerial(String serial)throws Exception{var rows=db.query("SELECT * FROM issued_certificates WHERE serial_number=?",serial);return rows.isEmpty()?null:rows.getFirst();}
  boolean otherHolder(String common,String actor)throws Exception{return db.query("SELECT valid_until FROM issued_certificates WHERE common_name=? AND revoked_at IS NULL AND created_by<>?",common,actor).stream().anyMatch(r->instant(r.get("valid_until"),Instant.EPOCH).isAfter(Instant.now()));}
  Map<String,Object>revokeContent(X509Certificate cert,String actor)throws Exception{return db.transaction(c->{var rows=Database.query(c,"SELECT id,revoked_at FROM issued_certificates WHERE serial_number=?",cert.getSerialNumber().toString());if(!rows.isEmpty()){var row=rows.getFirst();boolean changed=row.get("revoked_at")==null;if(changed)Database.update(c,"UPDATE issued_certificates SET revoked_at=? WHERE id=?",now(),row.get("id"));return m("id",row.get("id"),"changed",changed);}Database.update(c,"INSERT INTO issued_certificates(serial_number,common_name,created_by,valid_from,valid_until,revoked_at,certificate_pem)VALUES(?,?,?,?,?,?,?)",cert.getSerialNumber().toString(),cn(cert),"revoked-by:"+actor,cert.getNotBefore().toInstant().toString(),cert.getNotAfter().toInstant().toString(),now(),pem(cert));return m("id",Database.inserted(c),"changed",true);});}
 }
